def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Find all prime factors
    prime_factors = []
    for i in range(2, a + 1):
        if a % i == 0 and is_prime(i):
            prime_factors.append(i)

    # Check if we have exactly 3 prime factors and their product equals a
    if len(prime_factors) == 3:
        product = prime_factors[0] * prime_factors[1] * prime_factors[2]
        return product == a

    # Check if we have fewer than 3 prime factors but can form 3 primes
    # This is more complex - we need to check if a can be factored into exactly 3 primes
    if len(prime_factors) < 3:
        return False

    # If we have more than 3 prime factors, we need to check if we can group them
    # into exactly 3 primes that multiply to give a
    # For simplicity, let's check if a is the product of exactly 3 distinct primes
    # This is the case when we have exactly 3 prime factors and each appears once

    # Let's rework this approach - we'll check all combinations of 3 primes
    primes = [i for i in range(2, a) if is_prime(i)]

    # Check if a is the product of exactly 3 primes
    count = 0
    temp_a = a
    for prime in primes:
        if temp_a % prime == 0:
            count += 1
            while temp_a % prime == 0:
                temp_a //= prime

    # If we used exactly 3 primes and the result is 1, then a is product of exactly 3 primes
    if count == 3 and temp_a == 1:
        return True

    # Simpler approach: check if a can be written as product of 3 primes
    # We'll check all combinations of 3 primes whose product equals a
    for i in range(len(primes)):
        for j in range(i, len(primes)):
            for k in range(j, len(primes)):
                if primes[i] * primes[j] * primes[k] == a:
                    return True

    return False
