def encode(message):
    vowels = 'aeiou'
    result = []

    for char in message:
        if char.isalpha():
            # Swap case
            if char.islower():
                swapped_char = char.upper()
            else:
                swapped_char = char.lower()

            # Replace vowels with letter 2 places ahead
            if swapped_char.lower() in vowels:
                if swapped_char.lower() == 'a':
                    replaced_char = 'c'
                elif swapped_char.lower() == 'e':
                    replaced_char = 'g'
                elif swapped_char.lower() == 'i':
                    replaced_char = 'k'
                elif swapped_char.lower() == 'o':
                    replaced_char = 'q'
                elif swapped_char.lower() == 'u':
                    replaced_char = 'w'

                # Preserve the original case
                if swapped_char.isupper():
                    result.append(replaced_char.upper())
                else:
                    result.append(replaced_char.lower())
            else:
                result.append(swapped_char)
        else:
            result.append(char)

    return ''.join(result)
