def minPath(grid, k):
    if not grid or not grid[0] or k <= 0:
        return []

    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up

    def dfs(row, col, path, remaining):
        if remaining == 0:
            return path[:]

        # Early termination: if current path is already lexicographically larger
        # than our best path, we can stop
        if best_path and len(path) > 0:
            # Compare prefix
            min_len = min(len(path), len(best_path))
            for i in range(min_len):
                if path[i] < best_path[i]:
                    break
                elif path[i] > best_path[i]:
                    return None
            # If we get here, prefix is equal, continue

        min_val = float('inf')
        best_result = None

        # Try all four directions
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < n and 0 <= new_col < n:
                path.append(grid[new_row][new_col])
                result = dfs(new_row, new_col, path, remaining - 1)
                path.pop()

                if result is not None:
                    if best_result is None or result < best_result:
                        best_result = result
                    # Update min_val for early termination
                    min_val = min(min_val, result[0] if result else float('inf'))

        return best_result

    # Find the minimum value in the grid to start with
    min_val = float('inf')
    for i in range(n):
        for j in range(n):
            min_val = min(min_val, grid[i][j])

    # We'll use a global best_path to track the minimum path
    best_path = []

    def find_min_path():
        # Try starting from each cell
        for i in range(n):
            for j in range(n):
                path = [grid[i][j]]
                result = dfs(i, j, path, k - 1)
                if result is not None:
                    if not best_path or result < best_path:
                        best_path[:] = result[:]

        return best_path[:]

    # Simpler approach: use a more direct method
    best_path = None

    def dfs_simple(row, col, path):
        if len(path) == k:
            nonlocal best_path
            if best_path is None or path < best_path:
                best_path = path[:]
            return

        # Try all four directions
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < n and 0 <= new_col < n:
                path.append(grid[new_row][new_col])
                dfs_simple(new_row, new_col, path)
                path.pop()

    # Try starting from each cell
    for i in range(n):
        for j in range(n):
            path = [grid[i][j]]
            dfs_simple(i, j, path)

    return best_path if best_path else []
